ClassExpression.Expression:
// WorkspaceOwnerStaleItems materialization: one row per workspace-owner per evaluation run from sig_stale_items.
declare query_parameters(startTime:datetime, endTime:datetime);
let WorkspaceOwnerStaleItems =
    ['sig_stale_items'] | where ['SnapshotUtc'] between (startTime .. endTime)
    // Use SnapshotUtc as the evaluation run timestamp; no additional filters beyond upstream population.
    | project
        Id = strcat(['WorkspaceId'], "||", ['OwnerUpn']),
        Timestamp = ['SnapshotUtc'],
        NewlyStaleCount = ['NewlyStaleCount'],
        OwnerUpn = ['OwnerUpn'],
        WorkspaceName = ['WorkspaceName'],
        ItemList = ['ItemList'];
WorkspaceOwnerStaleItems
